"""A short script to merge together HDDM files generated by mcwrapper using the Python interfaces created via hddm-py from the halld software suite.  """

import hddm_s
import hddm_r
import argparse
import os
import sys


def merge(files, out):
    """Merge HDDM files. Select the REST or simulation HDDM interface based on file name."""
    hddm = hddm_r if "rest" in files[0] else hddm_s
    events = 0
    fout=hddm.ostream(out)
    fout.compression = hddm.k_z_compression
    for f in files:
        for entry in hddm.istream(f):
            fout.write(entry)
            events += 1
    # Close before reading back.
    del fout
    actual = sum(1 for entry in hddm.istream(out))
    print("HDDM records: expected {0}, got {1}".format(events, actual))
    return 0 if actual == events else 1


def main(args):
    return merge(args.files, args.output)


if __name__ == "__main__":
    parser = argparse.ArgumentParser(description="Bundle and move MCwrapper outputs to another directory.")
    parser.add_argument("output")
    parser.add_argument("files", nargs="+")
    args = parser.parse_args()
    sys.exit(main(args))
